   ============================================ */
.pc-profile-section {
    width: 100%;
    padding: 50px;
    background: #87ceeb0d;
    box-sizing: border-box;
}

.pc-profile-container {
    width: 100%;
    max-width: 1160px;
    margin: 0 auto;
}

.pc-profile-row {
    display: flex;
    align-items: flex-start;
    gap: 50px;
}

.pc-profile-content {
    flex: 1 1 60%;
    max-width: 60%;
}

.pc-profile-image {
    flex: 1 1 35%;
    max-width: 35%;
}

.pc-profile-image img {
    position: sticky;
    top: 30px;
    display: block;
    width: 100%;
    height: 520px;
    object-fit: cover;
    object-position: center top;
}

.pc-profile-list {
    margin: 0;
    padding: 0;
    list-style: none;
}

.pc-profile-list li {
    position: relative;
    padding: 9px 0 9px 36px;
    color: #111111;
    font-size: 17px;
    font-weight: 600;
    line-height: 1.6;
}

.pc-profile-list li small {
    display: block;
    margin-top: 2px;
    color: #444444;
    font-size: 15px;
    font-weight: 500;
}

/* Breadcrumb Section */
.breadcrumb-section {
    padding: 14px 0;
    border-bottom: 1px solid #eee5e9;
    width: 100%;
}

/* Breadcrumb Navigation */
.breadcrumb-section .breadcrumb {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 0;
    font-family: 'Poppins', sans-serif;
    font-size: 14px;
}

/* Home Link */
.breadcrumb-section .breadcrumb-item a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
}

.breadcrumb-section .breadcrumb-item a:hover {
    color: var(--primary-color);
    text-decoration: underline;
}

/* Current Page */
.breadcrumb-section .breadcrumb-item.active {
    color: #555555;
    font-weight: 500;
}

/* Breadcrumb Separator */
.breadcrumb-section .breadcrumb-item + .breadcrumb-item::before {
    content: "/";
    color: #999999;
    padding-right: 10px;
    padding-left: 10px;
}

.speciality-nav-wrapper {
    display: flex;
    align-items: center;
}

.speciality-nav-wrapper > .nav-link {
    display: inline-flex;
    align-items: center;
}

.speciality-toggle {
    border: 0;
    background: transparent;
    padding-left: 4px;
    padding-right: 8px;
}

.speciality-toggle::after {
    margin-left: 0;
}

@media (min-width: 992px) {
    .speciality-dropdown:hover > .dropdown-menu {
        display: block;
        font-size: 14px;
    }
}

/* Appointment Modal */
.appointment-modal {
    font-family: 'Poppins', sans-serif;
    border: none;
    border-radius: 14px;
    overflow: hidden;
}

.appointment-modal .modal-header {
    background: var(--primary-color);
    color: #fff;
    padding: 20px 24px;
}

.appointment-modal .modal-title {
    font-size: 19px;
    font-weight: 600;
    color: white;
}

.appointment-modal .btn-close {
    filter: brightness(0) invert(1);
}

.appointment-modal .form-label {
    font-size: 13px;
    font-weight: 500;
    color: #333;
}

.appointment-modal .form-control {
    padding: 11px 12px;
    font-size: 13px;
    border: 1px solid #e2d8dd;
    border-radius: 7px;
}

.appointment-modal .form-control:focus {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(176, 91, 122, 0.12);
}

.appointment-submit {
    background: var(--primary-color);
    border: 1px solid var(--primary-color);
    color: #fff;
    padding: 12px;
    font-size: 14px;
    font-weight: 500;
    border-radius: 7px;
}

.appointment-submit:hover {
    background: var(--primary-color);
    border-color: var(--primary-color);
    color: #fff;
}

@media (max-width: 576px) {
    .appointment-modal .modal-body {
        padding: 20px !important;
    }
}

/* Pregnancy Care Section */
.pregnancy-care-section {
    padding: 40px;
    background: #fff;
    font-family: 'Poppins', sans-serif;
}

.pregnancy-care-image {
    width: 100%;
    height: 100%;
    min-height: 420px;
    overflow: hidden;
    border-radius: 14px;
    background: #f8f0f4;
}

.pregnancy-care-image img {
    width: 100%;
    height: 100%;
    /* min-height: 420px; */
    object-fit: cover;
    display: block;
}

.pregnancy-care-content .section-tag {
    display: inline-block;
    /* margin-bottom: 12px; */
}

.pregnancy-care-content .section-title {
    margin-bottom: 22px;
    line-height: 1.4;
}

.pregnancy-care-content p {
    color: #666;
    font-size: 14px;
    line-height: 1.9;
    margin-bottom: 16px;
}

.pregnancy-care-content h3 {
    color: #333;
    font-size: 19px;
    font-weight: 600;
    margin: 24px 0 16px;
}

.pregnancy-care-list {
    list-style: none;
    padding: 0;
    margin: 0 0 25px;
}

.pregnancy-care-list li {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    color: #555;
    font-size: 14px;
    line-height: 1.7;
    margin-bottom: 12px;
}

.pregnancy-care-list i {
    color: var(--primary-color);
    font-size: 17px;
    margin-top: 3px;
    flex-shrink: 0;
}

.blog-content img, .blogs-section a.blog-card {
    display: block;
    text-decoration: none;
    color: inherit;
}

.blogs-section .container > div:first-child img {
    width: 100%;
    max-width: 700px;
    height: 350px;
    object-fit: cover;
    display: block;
    margin: 20px;
}

.blog-card {
    display: block;
    text-decoration: none;
    color: inherit;
    border-radius: 10px;
}

.read-more {
    display: inline-block;
    margin-top: 0px;
    margin-bottom: 5px;
    color: var(--primary-color);
    font-weight: 600;
    font-size: 15px;
}


.float-contact {
    position: fixed;
    left: 18px;
    bottom: 18px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    z-index: 1000;
}

.float-contact a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background-color: var(--primary-color);
    color: var(--white);
    font-size: 24px;
    text-decoration: none;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.22);
    transition: var(--transition);
}

.float-contact a:hover, .float-contact a:focus {
    color: var(--white);
    transform: translateY(-3px);
}

.float-contact .float-whatsapp {
    background-color: #25d366;
}


.back-to-top {
    position: fixed;
    right: 18px;
    bottom: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 46px;
    height: 46px;
    border: none;
    border-radius: 50%;
    background-color: var(--primary-color);
    color: var(--white);
    font-size: 22px;
    cursor: pointer;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.22);
    opacity: 0;
    visibility: hidden;
    transform: translateY(10px);
    transition: var(--transition);
    z-index: 1000;
}

.back-to-top.show {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.back-to-top:hover, .back-to-top:focus {
    color: var(--white);
    background-color: var(--btn-maroon-dark);
}


.lightbox {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 9999;
    background: rgba(0, 0, 0, 0.9);
    justify-content: center;
    align-items: center;
    padding: 20px;
}

.lightbox.active {
    display: flex;
}
.lightbox img {
    max-width: 90%;
    max-height: 85vh;
    width: auto;
    height: auto;
    object-fit: contain;
    border-radius: 10px;
    animation: lightboxZoom 0.3s ease;
}
.lightbox-close {
    position: absolute;
    top: 15px;
    right: 25px;
    color: #fff;
    font-size: 42px;
    background: transparent;
    border: none;
    cursor: pointer;
}

.site-footer a:hover {
    color: #ffffff;
}


@keyframes lightboxZoom {
    from {
        transform: scale(0.85);
        opacity: 0;
    }

    to {
        transform: scale(1);
        opacity: 1;
    }
}

.img-fluid {
    height: 250px;
}
.conditions-section{
    margin:20px !important;
}

.site-footer .footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    padding: 20px 0;
}

.site-footer .footer-bottom p {
    margin: 0;
    font-size: 13px;
    color: #d5e0e1;
}

.site-footer .footer-bottom .footer-credit {
    text-align: right;
}

.site-footer .footer-bottom .footer-credit a {
    color: #ffffff;
    font-weight: 600;
    text-decoration: none;
}

.site-footer .footer-bottom .footer-credit a:hover {
    text-decoration: underline;
}
